Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int countLines = Integer.parseInt(reader.readLine());
        String dataLine = reader.readLine();
        String regexPattern = "\\([\\w_]*\\)";
        String[] segments = dataLine.split(regexPattern);
        int maxWordCount = 0;
        for (String segment : segments) {
            maxWordCount = Math.max(maxWordCount, getMaxWordLength(segment));
        }
        Pattern pattern = Pattern.compile(regexPattern);
        Matcher matcher = pattern.matcher(dataLine);
        long insideWords = 0;
        while (matcher.find()) {
            String inside = stripParentheses(matcher.group());
            insideWords += Arrays.stream(inside.split("_"))
                                 .filter(s -> !s.isEmpty())
                                 .count();
        }
        writer.println(maxWordCount + " " + insideWords);
        writer.flush();
    }

    private static int getMaxWordLength(String s) {
        return Arrays.stream(s.split("_"))
                     .mapToInt(String::length)
                     .max()
                     .orElse(0);
    }

    private static String stripParentheses(String s) {
        return s.substring(1, s.length() - 1);
    }
}
